function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=text;if(cls)n.className=cls;return n;}
function icon(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','icon');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',icons[name]||icons.folder);svg.append(path);return svg;}
function button(text,fn,cls='secondary',symbol){const b=node('button',undefined,cls);b.type='button';if(symbol)b.append(icon(symbol));b.append(node('span',text));b.onclick=fn;return b;}
function badge(value){return node('span',UI.label(String(value||'Not recorded')), 'badge '+UI.tone(value));}
function dateLabel(value){if(!value)return'Not set';const d=new Date(String(value).length===10?value+'T12:00:00':value);return Number.isFinite(d.getTime())?d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):String(value);}
function display(value){if(value===null||value===undefined||value==='')return'Not recorded';if(typeof value==='boolean')return value?'Yes':'No';if(typeof value==='number')return value.toLocaleString();return String(value);}
