async function api(path,options={}){const r=await fetch(path,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),'X-CSRF-Token':csrf,...options.headers}});let data;try{data=await r.json();}catch{throw Error('The service could not return this view. Please try again.');}if(!r.ok){if(r.status===401){$('workspace').hidden=true;$('auth').hidden=false;}throw Error(typeof data.detail==='string'?data.detail:'Please check the required fields and try again.');}return data;}
