$('action-form').onsubmit=async e=>{e.preventDefault();const save=$('save-action'),original=save.textContent;save.disabled=true;save.textContent='Saving…';$('action-error').textContent='';try{const op=$('operation').value,args={};if(manifest[op].fields.some(f=>f.name==='org'))args.org=org;for(const input of $('fields').querySelectorAll('[name]')){let value=input.value;if(value===''){const def=manifest[op].fields.find(f=>f.name===input.name);if(!def.required)continue;}if(input.dataset.kind==='boolean')value=value==='true';if(['integer','number'].includes(input.dataset.kind))value=Number(value);if(input.name==='mapping'&&value)value=JSON.parse(value);args[input.name]=value;}const result=await api('/api/call/'+op,{method:'POST',body:JSON.stringify({arguments:args,reauth_password:$('reauth-password').value})});$('reauth-password').value='';$('action-dialog').close();if(op==='create_organization')await start();else await load(currentView);notice(manifest[op].write?'Record saved to your workspace.':'Results are ready.');if(result.result!==null&&typeof result.result==='object')details(result.result,op);}catch(error){$('action-error').textContent=error.message;}finally{save.disabled=false;save.textContent=original;}};
function uploadForm(isImport){const section=$('special');section.hidden=false;section.className='panel upload-panel';section.replaceChildren(node('h2',isImport?'Bring your existing work into the Studio':'Add supporting evidence'),node('p',isImport?'Preview every import before confirming. Imported statuses remain unverified until reviewed.':'Choose a meaningful title so the artifact is easy to find. Maximum file size: 5 MiB.'));const form=node('form');let module;if(isImport){const label=node('label','Import source');module=node('select');for(const value of ['risks','compliance_controls','security_policies','vendor_assessments','incident_tracker'])module.append(new Option(UI.label(value),value));label.append(module);form.append(label);}else{const label=node('label','Evidence title'),input=node('input');input.name='title';input.required=true;input.placeholder='For example: Access review — October';label.append(input);form.append(label);}const label=node('label',isImport?'CSV file':'Evidence file'),file=node('input');file.type='file';file.required=true;if(isImport)file.accept='.csv';label.append(file);form.append(label);const submit=node('button',isImport?'Preview import':'Upload evidence');submit.type='submit';form.append(submit);let previewed=false;const reset=()=>{previewed=false;submit.textContent='Preview import';};if(isImport){module.onchange=reset;file.onchange=reset;}form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const data=new FormData(form);data.set('org',org);data.set('file',file.files[0]);if(isImport){data.set('module',module.value);data.set('confirmed',previewed?'true':'false');}const kind=isImport?(previewed?'import':'preview'):'evidence',result=await api('/api/upload/'+kind,{method:'POST',body:data});if(kind==='preview'){previewed=true;submit.textContent='Confirm and import these rows';details(result.result,'Import preview');}else{await load(currentView);notice(isImport?'Import completed. Review the new records in your workspace.':'Evidence uploaded and ready for review.');if(typeof result.result==='object')details(result.result,'Import result');}}catch(error){notice(error.message,true);}finally{submit.disabled=false;}};section.append(form);}
