async function questionnaireForm(){
 const section=$('special');section.hidden=false;section.className='panel upload-panel';section.replaceChildren(node('h2','Third-party risk questionnaire'),node('p','Create the default 60-question assessment and record multiline responses. Narrative responses are not automatically scored.'));
 section.append(button('New third-party questionnaire',()=>openAction('create_assessment',{template_id:'builtin:third-party-risk-v1'})));
 const eligible=(cache.list_assessments||await read('list_assessments')).filter(a=>a.framework_label==='Third-party risk assessment — Default (60 questions), v1');
 if(!eligible.length)return;const label=node('label','Questionnaire'),select=node('select'),container=node('div');select.append(new Option('Select a questionnaire',''));for(const row of eligible)select.append(new Option(row.title,row.id));label.append(select);section.append(label,container);let version=0;
 select.onchange=async()=>{const current=++version;container.replaceChildren();if(!select.value)return;const assessment=select.value;try{const questions=await read('questions',{assessment});if(current===version)questionnaireResponses(container,questions,assessment);}catch(e){notice(e.message,true);}};
}
function questionnaireResponses(container,questions,assessment){
 const progress=node('p',undefined,'chart-note'),update=()=>progress.textContent=questions.filter(q=>String(q.rationale||'').trim()).length+' of '+questions.length+' responses saved';update();container.append(progress);
 for(const q of questions){const card=node('article',undefined,'question-card'),form=node('form'),label=node('label',q.code+' · '+q.prompt),input=node('textarea'),save=node('button','Save response'),status=node('small');input.value=q.rationale||'';input.maxLength=5000;input.rows=4;label.append(input);save.type='submit';status.setAttribute('role','status');form.append(label,save,status);card.append(form);container.append(card);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;status.textContent='Saving…';try{await call('save_questionnaire_response',{org,assessment,code:q.code,response:input.value});q.rationale=input.value.trim();update();status.textContent='Saved';}catch(err){status.textContent=err.message;}finally{save.disabled=false;}};}
}

async function brandingForm(section){
 const selectedOrg=org;const box=node('section',undefined,'branding-settings');
 box.append(node('h2','Report branding'),node('p','Upload your organization’s logo and set a consistent identity for executive and board PDF and Excel exports.'));
 section.append(box);
 try{
  const brand=await api('/api/report-branding/'+encodeURIComponent(selectedOrg));
  if(org!==selectedOrg||page!=='reports')return;
  if(!brand.can_edit){box.append(node('p','The workspace owner manages the saved report identity. Your report downloads use the organization’s current branding.'));return;}
  const form=node('form',undefined,'branding-form'),grid=node('div',undefined,'field-grid'),inputs={};
  for(const [key,labelText,type,max] of [['display_name','Report display name','text',100],['tagline','Tagline','text',160],['primary_color','Primary color','color'],['accent_color','Accent color','color'],['footer_note','Footer / confidentiality note','text',120]]){
   const label=node('label',labelText),input=node('input');input.name=key;input.type=type;input.value=type==='color'?'#'+brand[key]:brand[key];if(max)input.maxLength=max;input.required=key==='display_name';label.append(input);grid.append(label);inputs[key]=input;
  }
  const label=node('label','Organization logo'),file=node('input');file.type='file';file.name='logo';file.accept='image/png,image/jpeg';label.append(file,node('small','PNG or JPEG, up to 2 MiB and 8 million pixels. Logos are resized proportionally; transparent PNG works well.','field-help'));grid.append(label);
  const removeLabel=node('label',undefined,'branding-remove'),remove=node('input');remove.type='checkbox';removeLabel.append(remove,node('span','Remove the saved logo'));remove.disabled=!brand.has_logo;
  const preview=node('div',undefined,'brand-preview'),image=node('img'),identity=node('div'),heading=node('h3'),tagline=node('p'),note=node('p',undefined,'chart-note');image.alt='Report logo preview';identity.append(heading,tagline);preview.append(image,identity);note.textContent='Layout preview. Export a PDF to review page layout. Program Owner - Matthew Harris remains fixed on every report.';
  const update=()=>{heading.textContent=inputs.display_name.value;const rgb=inputs.primary_color.value.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4);heading.style.color=rgb.reduce((s,c,i)=>s+c*[.2126,.7152,.0722][i],0)<.179?inputs.primary_color.value:'#112c3a';tagline.textContent=inputs.tagline.value;preview.style.borderTopColor=inputs.accent_color.value;};
  for(const input of Object.values(inputs))input.addEventListener('input',update);
  let localLogo='';const showLogo=()=>{image.hidden=remove.checked||(!localLogo&&!brand.has_logo);if(!image.hidden)image.src=localLogo||'/api/report-branding/'+encodeURIComponent(selectedOrg)+'/logo?v='+encodeURIComponent(brand.updated_at);};
  // Use regular CSS classes for all layout; the preview's user-selected colors are applied as SVG-free CSSOM values.
  const error=node('p',undefined,'form-error');error.setAttribute('role','alert');
  file.onchange=()=>{error.textContent='';const selected=file.files[0];localLogo='';if(!selected){showLogo();return;}if(selected.size>2*1024*1024||!['image/png','image/jpeg'].includes(selected.type)){error.textContent='Choose a PNG or JPEG logo up to 2 MiB.';file.value='';showLogo();return;}remove.checked=false;const reader=new FileReader();reader.onload=()=>{localLogo=reader.result;showLogo();};reader.readAsDataURL(selected);};remove.onchange=showLogo;
  const save=node('button','Save report branding');save.type='submit';form.append(grid,removeLabel,preview,note,error,save);box.append(form);update();showLogo();
  form.onsubmit=async event=>{event.preventDefault();save.disabled=true;save.textContent='Saving…';error.textContent='';try{const data=new FormData(form);data.set('remove_logo',remove.checked?'true':'false');const result=await api('/api/report-branding/'+encodeURIComponent(selectedOrg),{method:'POST',body:data});Object.assign(brand,result);file.value='';remove.checked=false;remove.disabled=!brand.has_logo;localLogo='';showLogo();if(typeof XP!=='undefined'){await XP.refreshState();XP.applyBrand();}notice('Report branding saved. New PDF and Excel downloads will use this identity.');}catch(e){error.textContent=e.message;}finally{save.disabled=false;save.textContent='Save report branding';}};
 }catch(e){box.append(node('p',e.message,'form-error'),button('Retry branding settings',()=>load(currentView)));}
}
